// Some portions generated by Codex
package org.eclipse.rdf4j.sail.memory;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.stream.Stream;

import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.RDF;
import org.eclipse.rdf4j.sail.inferencer.InferencerConnection;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

class MemoryStoreExplicitInferredTransactionTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI SUBJECT = VF.createIRI("urn:test:subject");
	private static final IRI TYPE = VF.createIRI("urn:test:Class");
	private static final IRI GRAPH = VF.createIRI("urn:test:graph");

	private MemoryStore store;

	@BeforeEach
	void setUp() {
		store = new MemoryStore();
		store.init();
	}

	@AfterEach
	void tearDown() {
		store.shutDown();
	}

	static Stream<Arguments> isolationLevelsAndContexts() {
		return Stream.of(IsolationLevels.NONE, IsolationLevels.READ_COMMITTED, IsolationLevels.SNAPSHOT_READ,
				IsolationLevels.SNAPSHOT, IsolationLevels.SERIALIZABLE)
				.flatMap(level -> Stream.of(Arguments.of(level, null), Arguments.of(level, GRAPH)));
	}

	static Stream<Arguments> isolatedLevelsAndContexts() {
		return isolationLevelsAndContexts().filter(arguments -> arguments.get()[0] != IsolationLevels.NONE);
	}

	static Stream<Resource> contexts() {
		return Stream.of(null, GRAPH);
	}

	@ParameterizedTest
	@MethodSource("isolationLevelsAndContexts")
	void removedExplicitStatementCanBeReaddedAsInferred(IsolationLevels level, Resource context) {
		try (InferencerConnection connection = (InferencerConnection) store.getConnection()) {
			addExplicit(connection, level, context);

			connection.begin(level);
			connection.removeStatements(SUBJECT, RDF.TYPE, TYPE, context);
			connection.flushUpdates();
			assertTrue(connection.addInferredStatement(SUBJECT, RDF.TYPE, TYPE, context));
			assertStatement(connection, context, false, true);
			connection.commit();

			assertCommittedStatement(context, false, true);
		}
	}

	@ParameterizedTest
	@MethodSource("isolationLevelsAndContexts")
	void clearedExplicitStatementCanBeReaddedAsInferred(IsolationLevels level, Resource context) {
		try (InferencerConnection connection = (InferencerConnection) store.getConnection()) {
			addExplicit(connection, level, context);

			connection.begin(level);
			connection.clear(context);
			connection.flushUpdates();
			assertTrue(connection.addInferredStatement(SUBJECT, RDF.TYPE, TYPE, context));
			connection.commit();

			assertCommittedStatement(context, false, true);
		}
	}

	@ParameterizedTest
	@MethodSource("isolationLevelsAndContexts")
	void promotedStatementSurvivesClearingInferences(IsolationLevels level, Resource context) {
		try (InferencerConnection connection = (InferencerConnection) store.getConnection()) {
			connection.begin(level);
			assertTrue(connection.addInferredStatement(SUBJECT, RDF.TYPE, TYPE, context));
			connection.commit();
			assertCommittedStatement(context, false, true);

			connection.begin(level);
			connection.addStatement(SUBJECT, RDF.TYPE, TYPE, context);
			connection.clearInferred(context);
			connection.commit();

			assertCommittedStatement(context, true, true);
		}
	}

	@ParameterizedTest
	@MethodSource("isolatedLevelsAndContexts")
	void rollbackPreservesExplicitAndInferredState(IsolationLevels level, Resource context) {
		try (InferencerConnection connection = (InferencerConnection) store.getConnection()) {
			addExplicit(connection, level, context);

			connection.begin(level);
			connection.removeStatements(SUBJECT, RDF.TYPE, TYPE, context);
			connection.flushUpdates();
			assertTrue(connection.addInferredStatement(SUBJECT, RDF.TYPE, TYPE, context));
			connection.rollback();
			assertCommittedStatement(context, true, true);

			connection.begin(level);
			connection.clear(context);
			connection.commit();
			connection.begin(level);
			assertTrue(connection.addInferredStatement(SUBJECT, RDF.TYPE, TYPE, context));
			connection.commit();

			connection.begin(level);
			connection.addStatement(SUBJECT, RDF.TYPE, TYPE, context);
			connection.clearInferred(context);
			connection.rollback();
			assertCommittedStatement(context, false, true);
		}
	}

	@ParameterizedTest
	@MethodSource("contexts")
	void snapshotReadersRetainStatementRolesAcrossCommits(Resource context) {
		try (InferencerConnection writer = (InferencerConnection) store.getConnection();
				InferencerConnection explicitSnapshot = (InferencerConnection) store.getConnection();
				InferencerConnection inferredSnapshot = (InferencerConnection) store.getConnection()) {
			addExplicit(writer, IsolationLevels.SNAPSHOT, context);
			explicitSnapshot.begin(IsolationLevels.SNAPSHOT);
			assertStatement(explicitSnapshot, context, true, true);

			writer.begin(IsolationLevels.SNAPSHOT);
			writer.removeStatements(SUBJECT, RDF.TYPE, TYPE, context);
			writer.flushUpdates();
			assertTrue(writer.addInferredStatement(SUBJECT, RDF.TYPE, TYPE, context));
			writer.commit();
			assertCommittedStatement(context, false, true);
			assertStatement(explicitSnapshot, context, true, true);

			inferredSnapshot.begin(IsolationLevels.SNAPSHOT);
			assertStatement(inferredSnapshot, context, false, true);

			writer.begin(IsolationLevels.SNAPSHOT);
			writer.addStatement(SUBJECT, RDF.TYPE, TYPE, context);
			writer.clearInferred(context);
			writer.commit();
			assertCommittedStatement(context, true, true);
			assertStatement(explicitSnapshot, context, true, true);
			assertStatement(inferredSnapshot, context, false, true);
			inferredSnapshot.rollback();
			explicitSnapshot.rollback();
		}
	}

	private static void addExplicit(InferencerConnection connection, IsolationLevels level, Resource context) {
		connection.begin(level);
		connection.addStatement(SUBJECT, RDF.TYPE, TYPE, context);
		connection.commit();
	}

	private void assertCommittedStatement(Resource context, boolean explicit, boolean inferredOrExplicit) {
		try (InferencerConnection reader = (InferencerConnection) store.getConnection()) {
			assertStatement(reader, context, explicit, inferredOrExplicit);
		}
	}

	private static void assertStatement(InferencerConnection connection, Resource context, boolean explicit,
			boolean inferredOrExplicit) {
		assertEquals(explicit, connection.hasStatement(SUBJECT, RDF.TYPE, TYPE, false, context),
				"explicit statement visibility");
		assertEquals(inferredOrExplicit, connection.hasStatement(SUBJECT, RDF.TYPE, TYPE, true, context),
				"statement visibility including inferences");
	}
}
